      "content": "{\n  \"name\": \"dsh-better-sidebar\",\n  \"version\": \"0.28.0\",\n  \"description\": \"Better Sidebar for DSH — file tree, editor, changes, tasks and side chat in one column, separate for every conversation. Also exposes a service other plugins use to register sidebar tabs and file viewers.\",\n  \"type\": \"module\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/omdsh-dev/DSH-better-sidebar\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./client/service\": {\n      \"types\": \"./lib/types/client/service.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./client/api\": {\n      \"types\": \"./lib/types/client/service.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"packageManager\": \"pnpm@11.8.0\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\",\n        \"@deepseek-ai/dsh-client-modules\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"manifestVersion\": 1\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/client-registry.js\",\n    \"lib/client-editor.js\",\n    \"lib/client-locale.js\",\n    \"lib/client-mermaid.js\",\n    \"lib/client-terminal.js\",\n    \"lib/types/**/*.d.ts\",\n    \"src\",\n    \"scripts/install.sh\",\n    \"scripts/install.ps1\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README_ZH.md\",\n    \"LICENSE\",\n    \"icon.svg\",\n    \"locale/*.json\"\n  ],\n  \"scripts\": {\n    \"build\": \"node -e \\\"require('node:fs').rmSync('lib',{recursive:true,force:true})\\\" && tsc -p tsconfig.build.json && tsdown\",\n    \"prepublishOnly\": \"pnpm build\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"bundle\": \"tsdown\",\n    \"watch\": \"tsdown --watch\",\n    \"prepare\": \"tsdown\",\n    \"test\": \"vitest run\",\n    \"test:windows\": \"vitest run --maxWorkers=1\",\n    \"test:mount\": \"bash scripts/e2e-mount.sh\",\n    \"test:mount:aggregate\": \"bash scripts/e2e-aggregate-mount.sh\",\n    \"clean\": \"node -e \\\"require('node:fs').rmSync('lib',{recursive:true,force:true})\\\"\",\n    \"check:consumer-types\": \"bash scripts/check-consumer-types.sh\",\n    \"check:engines\": \"node --experimental-strip-types scripts/win-engine-check.mjs --assert\",\n    \"lint\": \"eslint .\"\n  },\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-subagent\": \"^0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.1-rc.1\",\n    \"@huanlin/dsh-plugin-better-locale\": \"^0.1.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@huanlin/dsh-plugin-better-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": {\n      \"optional\": true\n    }\n  },\n  \"dependencies\": {\n    \"@codemirror/commands\": \"^6.10.4\",\n    \"@codemirror/lang-cpp\": \"^6.0.3\",\n    \"@codemirror/lang-css\": \"^6.3.1\",\n    \"@codemirror/lang-go\": \"^6.0.1\",\n    \"@codemirror/lang-html\": \"^6.4.12\",\n    \"@codemirror/lang-java\": \"^6.0.2\",\n    \"@codemirror/lang-javascript\": \"^6.2.5\",\n    \"@codemirror/lang-json\": \"^6.0.2\",\n    \"@codemirror/lang-markdown\": \"^6.5.2\",\n    \"@codemirror/lang-php\": \"^6.0.2\",\n    \"@codemirror/lang-python\": \"^6.2.1\",\n    \"@codemirror/lang-rust\": \"^6.0.2\",\n    \"@codemirror/lang-sql\": \"^6.10.0\",\n    \"@codemirror/lang-vue\": \"^0.1.3\",\n    \"@codemirror/lang-xml\": \"^6.1.0\",\n    \"@codemirror/lang-yaml\": \"^6.1.3\",\n    \"@codemirror/language\": \"^6.12.4\",\n    \"@codemirror/legacy-modes\": \"^6.5.3\",\n    \"@codemirror/search\": \"^6.7.1\",\n    \"@codemirror/state\": \"^6.7.1\",\n    \"@codemirror/view\": \"^6.43.8\",\n    \"@deepseek-ai/schemastery\": \"~3.18.5\",\n    \"@formkit/auto-animate\": \"^0.10.0\",\n    \"@lezer/highlight\": \"^1.2.3\",\n    \"@xterm/addon-fit\": \"^0.11.0\",\n    \"@xterm/xterm\": \"^6.0.0\",\n    \"clsx\": \"^2.1.1\",\n    \"dompurify\": \"^3.4.14\",\n    \"mermaid\": \"^11.16.1\",\n    \"react-icons\": \"5.7.0\",\n    \"rxjs\": \"^7.8.2\",\n    \"ws\": \"^8.18.0\",\n    \"yaml\": \"^2.9.1\"\n  },\n  \"devDependencies\": {\n    \"@cordisjs/plugin-loader\": \"^1.0.0-rc.5\",\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/cordis-plugin-group\": \"1.0.5\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.0.10\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-agent-loop\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-ptc-runtime\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-session-persistence\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-subagent\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-util-code-language\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-util-time\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.1-rc.1\",\n    \"@deepseek-ai/dsh-working-directory\": \"0.2.1-rc.1\",\n    \"@eslint/js\": \"^10.0.1\",\n    \"@huanlin/dsh-plugin-better-locale\": \"^0.1.0\",\n    \"@playwright/test\": \"^1.62.1\",\n    \"@shikijs/langs\": \"^4.3.1\",\n    \"@types/mdast\": \"^4.0.4\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"@types/ws\": \"^8.5.10\",\n    \"anser\": \"^2.3.5\",\n    \"cordis\": \"^4.0.0-rc.8\",\n    \"diff\": \"^9.0.0\",\n    \"eslint\": \"^10.9.1\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"globals\": \"^17.12.0\",\n    \"immer\": \"^10.1.1\",\n    \"jsdom\": \"^29.1.1\",\n    \"katex\": \"^0.16.47\",\n    \"lightningcss\": \"^1.32.0\",\n    \"mdast-util-from-markdown\": \"^2.0.3\",\n    \"mdast-util-gfm\": \"^3.1.0\",\n    \"mdast-util-math\": \"^3.0.0\",\n    \"micromark-core-commonmark\": \"^2.0.3\",\n    \"micromark-extension-gfm\": \"^3.0.0\",\n    \"micromark-extension-math\": \"^3.1.0\",\n    \"micromark-factory-space\": \"^2.0.1\",\n    \"micromark-util-character\": \"^2.1.1\",\n    \"micromark-util-classify-character\": \"^2.0.1\",\n    \"micromark-util-sanitize-uri\": \"^2.0.1\",\n    \"micromark-util-symbol\": \"^2.0.1\",\n    \"micromark-util-types\": \"^2.0.2\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"18.2.0\",\n    \"shiki\": \"^4.3.1\",\n    \"simple-icons\": \"^16.32.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.6.0\",\n    \"typescript-eslint\": \"^8.69.0\",\n    \"unrun\": \"^0.2.39\",\n    \"vitest\": \"^4.1.8\",\n    \"zustand\": \"~4.4.7\"\n  },\n  \"icon\": \"./icon.svg\"\n}\n"
